'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var Fcn = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Fcn, 'function', 'main export is a function' );
	t.end();
});

tape( 'a function instance has a `toString` method', function test( t ) {
	var f = new Fcn( 'x', 'y', 'return x + y' );
	t.strictEqual( hasProp( f, 'toString' ), true, 'has property' );
	t.strictEqual( isFunction( f.toString ), true, 'has method' );
	t.end();
});

tape( 'the method returns a string representation of the function', function test( t ) {
	var f;
	var v;

	f = new Fcn( 'x', 'y', 'return x + y' );
	v = f.toString();
	t.strictEqual( typeof v, 'string', 'returns a string' );
	t.end();
});

tape( 'the method returns a string containing the function body', function test( t ) {
	var f;
	var v;

	f = new Fcn( 'x', 'y', 'return x + y' );
	v = f.toString();
	t.strictEqual( typeof v, 'string', 'returns a string' );
	t.notEqual( v.indexOf( 'return x + y' ), -1, 'contains function body' );
	t.end();
});

tape( 'the method returns a string containing the parameter names', function test( t ) {
	var f;
	var v;

	f = new Fcn( 'x', 'y', 'return x + y' );
	v = f.toString();
	t.strictEqual( typeof v, 'string', 'returns a string' );
	t.notEqual( v.indexOf( 'x' ), -1, 'contains parameter name' );
	t.notEqual( v.indexOf( 'y' ), -1, 'contains parameter name' );
	t.end();
});
